def match(pattern: str, text: str) -> bool:
    """
    Implements regex matching using recursion and backtracking.
    Supports literal characters, '.', '*' (zero or more), and '+' (one or more).
    """

    def is_match(p: str, t: str) -> bool:
        if not p:
            return not t

        first_match = bool(t) and (p[0] == t[0] or p[0] == '.')

        if len(p) >= 2 and p[1] in {'*', '+'}:
            if p[1] == '*':
                return (is_match(p[2:], t) or 
                        (first_match and is_match(p, t[1:])))
            elif p[1] == '+':
                return first_match and (is_match(p[2:], t) or 
                                       is_match(p, t[1:]))

        return first_match and is_match(p[1:], t[1:])

    return is_match(pattern, text)

def match(pattern: str, text: str) -> bool:
    """
    Implements regex matching using dynamic programming with memoization.
    Supports literal characters, '.', '*' (zero or more), and '+' (one or more).
    """
    memo = {}

    def dp(i: int, j: int) -> bool:
        if (i, j) in memo:
            return memo[(i, j)]

        if j == len(pattern):
            result = i == len(text)
        else:
            first_match = i < len(text) and (text[i] == pattern[j] or pattern[j] == '.')

            if j + 1 < len(pattern) and pattern[j + 1] in {'*', '+'}:
                if pattern[j + 1] == '*':
                    result = dp(i, j + 2) or (first_match and dp(i + 1, j))
                else:  # pattern[j + 1] == '+'
                    result = first_match and (dp(i + 1, j) or (i + 1 < len(text) and dp(i + 1, j + 2)))
            else:
                result = first_match and dp(i + 1, j + 1)

        memo[(i, j)] = result
        return result

    return dp(0, 0)

