    """
    Implements regex matching using a recursive backtracking approach to explore all potential matches.
    Supports literal characters, '.', '*' (zero or more), and '+' (one or more).
    """

    def backtrack(p_index: int, t_index: int) -> bool:
        if p_index == len(pattern):
            return t_index == len(text)

        first_match = (t_index < len(text) and 
                       (pattern[p_index] == text[t_index] or pattern[p_index] == '.'))

        if p_index + 1 < len(pattern):
            if pattern[p_index + 1] == '*':
                return (backtrack(p_index + 2, t_index) or 
                        (first_match and backtrack(p_index, t_index + 1)))
            elif pattern[p_index + 1] == '+':
                return first_match and (backtrack(p_index + 2, t_index) or 
                                        backtrack(p_index, t_index + 1))

        return first_match and backtrack(p_index + 1, t_index + 1)

    return backtrack(0, 0)
